import React, { useEffect, useState } from 'react';
import { fetchReviews } from '../api/reviewApi';
import axios from '../api/axiosConfig';

function Magazine() {
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(false);
  const [hoveredReviewer, setHoveredReviewer] = useState(null);

  // 급상승 리뷰어 데이터
  const topReviewers = [
    {
      id: 1,
      name: '뷰티민지',
      avatar: '/images/minji.jpg',
      specialty: '뷰티',
      followerGain: 324,
      quote: '진정성 있는 리뷰가 제 원칙이에요'
    },
    {
      id: 2,
      name: '스킨케어수아',
      avatar: '/images/sua.jpg',
      specialty: '스킨케어',
      followerGain: 287,
      quote: '민감한 피부를 위한 꿀팁 공유해요'
    },
    {
      id: 3,
      name: '인플루언서채희',
      avatar: '/images/chaehee.jpg',
      specialty: '퍼퓸 & 프래그런스',
      followerGain: 198,
      quote: '데일리룩 추천은 저에게 맡겨주세요'
    }
  ];

  useEffect(() => {
    const load = async () => {
      try {
        setLoading(true);
        const reviewsRes = await fetchReviews({ page: 1, limit: 8 });
        const texts = reviewsRes.data.map(r => r.text);
        const resp = await axios.post('/ai/summarize', { texts });
        setSummary(resp.data.summary);
      } catch (err) {
        console.error('magazine load failed', err);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  return (
    <div 
      style={{ 
        padding: 20, 
        minHeight: '100vh',
        background: 'linear-gradient(180deg, #fff 0%, #fff5f7 50%, #faf5ff 100%)',
        position: 'relative'
      }}
    >
      <h1>📰 AI 리뷰 매거진</h1>
      <p style={{ color: '#666' }}>AI가 여러 리뷰를 뽑아 트렌드와 핵심을 정리해드립니다.</p>

      {/* 급상승 리뷰어 섹션 */}
      <div style={{ maxWidth: 900, margin: '40px auto' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 20 }}>
          <span style={{ fontSize: 24 }}>🚀</span>
          <div>
            <h2 style={{ margin: 0, fontSize: 22, fontWeight: 800, color: '#1a1a2e' }}>급상승 리뷰어</h2>
            <p style={{ margin: 0, color: '#888', fontSize: 13 }}>이번 주 주목할 크리에이터</p>
          </div>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 16 }}>
          {topReviewers.map((reviewer, idx) => (
            <div
              key={reviewer.id}
              onMouseEnter={() => setHoveredReviewer(reviewer.id)}
              onMouseLeave={() => setHoveredReviewer(null)}
              style={{
                background: '#fffef5',
                borderRadius: 16,
                padding: '24px 20px',
                textAlign: 'center',
                boxShadow: hoveredReviewer === reviewer.id 
                  ? '0 8px 30px rgba(0,0,0,0.1)' 
                  : '0 2px 12px rgba(0,0,0,0.05)',
                transition: 'all 0.3s ease',
                transform: hoveredReviewer === reviewer.id ? 'translateY(-4px)' : 'translateY(0)',
                cursor: 'pointer',
                position: 'relative'
              }}
            >
              {/* 1위 뱃지 */}
              {idx === 0 && (
                <div style={{
                  position: 'absolute',
                  top: 12,
                  right: 12,
                  background: 'linear-gradient(135deg, #ff6b9d, #ff8a65)',
                  color: 'white',
                  padding: '4px 10px',
                  borderRadius: 12,
                  fontSize: 11,
                  fontWeight: 700
                }}>
                  🏆 1위
                </div>
              )}

              {/* 이름 라벨 */}
              <div style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 6,
                background: '#e8f5e9',
                borderRadius: 16,
                padding: '5px 12px',
                marginBottom: 16
              }}>
                <span style={{ fontSize: 12 }}>🌿</span>
                <span style={{ fontSize: 12, fontWeight: 600, color: '#2e7d32' }}>{reviewer.name}</span>
              </div>

              {/* 프로필 이미지 */}
              <div style={{
                width: 80,
                height: 80,
                borderRadius: '50%',
                overflow: 'hidden',
                margin: '0 auto 12px',
                border: '3px solid #fff',
                boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                background: '#f0f0f0'
              }}>
                <img 
                  src={reviewer.avatar} 
                  alt={reviewer.name}
                  style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                  onError={(e) => {
                    e.target.style.display = 'none';
                    e.target.parentElement.innerHTML = `<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:32px;background:linear-gradient(135deg,#ff9a9e,#fecfef)">👤</div>`;
                  }}
                />
              </div>

              {/* 이름 */}
              <h3 style={{ fontSize: 16, fontWeight: 700, color: '#1a1a2e', marginBottom: 4 }}>
                {reviewer.name}
              </h3>

              {/* 전문 분야 */}
              <p style={{ color: '#888', fontSize: 12, marginBottom: 12 }}>
                {reviewer.specialty} 전문
              </p>

              {/* 팔로워 증가 */}
              <div style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 6,
                background: 'linear-gradient(135deg, #e8f5e9, #c8e6c9)',
                padding: '6px 14px',
                borderRadius: 16,
                marginBottom: 12
              }}>
                <span style={{ color: '#2e7d32', fontWeight: 600, fontSize: 13 }}>팔로워</span>
                <span style={{ color: '#43a047', fontWeight: 800, fontSize: 14 }}>+{reviewer.followerGain}</span>
              </div>

              {/* 한 마디 */}
              <p style={{ color: '#666', fontSize: 12, fontStyle: 'italic', lineHeight: 1.4 }}>
                "{reviewer.quote}"
              </p>
            </div>
          ))}
        </div>
      </div>

      {loading && <p>요약 생성 중...</p>}

      {summary && (
        <div style={{ marginTop: 16, padding: 16, background: '#fff', borderRadius: 8, boxShadow: '0 8px 20px rgba(0,0,0,0.04)' }}>
          <div dangerouslySetInnerHTML={{ __html: summary.replace(/\n/g, '<br/>') }} />
        </div>
      )}
    </div>
  );
}

export default Magazine;
